"""Write Radicale rights so ICS collections are read-only for the owner."""

import os
import re
from pathlib import Path


def _token(value: str) -> str:
    return re.escape(value.strip())


def build_rights(*, owner: str, internal: str) -> str:
    user = _token(owner)
    hub = _token(internal)
    # R/W = untagged collections (root, principal); r/w = calendar collections.
    # MKCOL on /{user}/ needs W; PROPFIND/PUT on calendars need r/w.
    return (
        "# Generated by calendar-hub. ICS paths under /{user}/ics- are owner read-only.\n"
        "[internal]\n"
        f"user: ^{hub}$\n"
        "collection: .*\n"
        "permissions: RrWw\n"
        "\n"
        "[owner-root]\n"
        f"user: ^{user}$\n"
        "collection:\n"
        "permissions: R\n"
        "\n"
        "[owner-principal]\n"
        f"user: ^{user}$\n"
        f"collection: ^{user}$\n"
        "permissions: R\n"
        "\n"
        "[owner-ics]\n"
        f"user: ^{user}$\n"
        # fullmatch: prefix alone does not consume the rest of the path.
        f"collection: ^{user}/ics-.*\n"
        "permissions: Rr\n"
        "\n"
        "[owner-rw]\n"
        f"user: ^{user}$\n"
        f"collection: ^{user}/(?!ics-).*\n"
        "permissions: RrWw\n"
    )


def main() -> None:
    owner = os.environ.get("HUB_USER", "").strip()
    internal = os.environ.get("HUB_INTERNAL_USER", "").strip()
    if not owner or not internal:
        raise SystemExit(
            "HUB_USER and HUB_INTERNAL_USER are required for Radicale rights"
        )
    path = Path(os.environ.get("HUB_RADICALE_RIGHTS", "/config/rights"))
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(build_rights(owner=owner, internal=internal), encoding="utf-8")


if __name__ == "__main__":
    main()
